<?php
declare(strict_types=1);

namespace Zara\Container\Compiler;

/**
 * Contract implemented by CompiledServiceFactory (generated by
 * ContainerCompiler and never present as a source file in the repository).
 * Type-hinting against this interface instead of the generated class avoids
 * a static dependency on a file that only exists after compilation.
 */
interface CompiledFactoryInterface
{
    public function has(string $id): bool;
    public function get(string $id): object;

    public function set(string $id, object $instance): void;
}
